<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\File;
use Illuminate\Support\Facades\Schema;
use Illuminate\Support\Facades\Storage;

/**
 * Full snapshot of the platform data. Replaces the rows of every table below,
 * so run it on a freshly migrated database: php artisan db:seed --class=DataSeeder
 * API tokens and mail secrets are not included; set the mail keys again from the admin panel.
 */
class DataSeeder extends Seeder
{
    public function run(): void
    {
        $tables = $this->data();

        Schema::disableForeignKeyConstraints();

        foreach (array_reverse(array_keys($tables)) as $table) {
            if (Schema::hasTable($table)) {
                DB::table($table)->delete();
            }
        }

        foreach ($tables as $table => $rows) {
            if (! Schema::hasTable($table)) {
                continue;
            }

            $columns = Schema::getColumnListing($table);

            foreach (array_chunk($rows, 100) as $chunk) {
                DB::table($table)->insert(array_map(
                    fn (array $row): array => array_intersect_key($row, array_flip($columns)),
                    $chunk,
                ));
            }
        }

        Schema::enableForeignKeyConstraints();

        $this->copyImages();
    }

    private function copyImages(): void
    {
        $source = database_path('seeders/data/storage');

        if (! File::isDirectory($source)) {
            return;
        }

        foreach (File::allFiles($source) as $file) {
            Storage::disk('public')->put($file->getRelativePathname(), File::get($file->getPathname()));
        }
    }

